//   node --experimental-strip-types DROP8_refactor_025_open_arena_kill_limit_match_cycle_patch_FIXED_v1.ts --rollback
import { copyFileSync, cpSync, existsSync, mkdirSync, readFileSync, readdirSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, isAbsolute, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync } from 'node:zlib';
import { spawnSync } from 'node:child_process';

type Entry={path:string;purpose:string;mode:'modify'|'create';acceptedBeforeSha256:string[];afterSha256:string;content:string};
type Payload={marker:string;priorMarker:string;entries:Entry[]};
type Manifest={patchId:string;patchFile:string;createdAt:string;projectRoot:string;files:Array<{path:string;existed:boolean;beforeSha256:string;eol:'LF'|'CRLF';bom:boolean}> ;createdFiles:string[];generatedDirs:Array<{path:string;existed:boolean}>};

const PATCH_ID='DROP8 Refactor 025 Open Arena Kill Limit & Match Cycle FIXED v1';
const PATCH_FILE='DROP8_refactor_025_open_arena_kill_limit_match_cycle_patch_FIXED_v1.ts';
const BACKUP_NAME='refactor_025_open_arena_kill_limit_match_cycle_FIXED_v1';
const PAYLOAD_B64='';
const payload=JSON.parse(gunzipSync(Buffer.from(PAYLOAD_B64,'base64')).toString('utf8')) as Payload;
const args=process.argv.slice(2),dryRun=args.includes('--dry-run'),rollbackIndex=args.indexOf('--rollback');
const internal=process.env.DROP8_PATCH_INTERNAL==='1',forceFail=process.env.DROP8_PATCH_FORCE_FAIL==='1';
const scriptDir=dirname(fileURLToPath(import.meta.url));
const sha=(data:Buffer|string)=>createHash('sha256').update(data).digest('hex');
const read=(path:string)=>readFileSync(path,'utf8');
const timestamp=()=>new Date().toISOString().replace(/[:.]/g,'-');
const hasBom=(text:string)=>text.charCodeAt(0)===0xfeff;
const eol=(text:string):'LF'|'CRLF'=>text.includes('\r\n')?'CRLF':'LF';
function safe(path:string){const rel=path.replace(/\\/g,'/');if(!rel||rel.startsWith('/')||rel.split('/').includes('..'))throw new Error(`안전하지 않은 경로: ${path}`);return rel;}
function isRoot(path:string){return existsSync(join(path,'package.json'))&&existsSync(join(path,'server/src/rooms/Drop8Room.ts'))&&existsSync(join(path,'client/src/main.ts'))&&existsSync(join(path,'shared/src/index.ts'));}
function findRoot(){for(const start of [process.cwd(),scriptDir]){let cursor=resolve(start);for(let i=0;i<10;i++){if(isRoot(cursor))return cursor;const parent=dirname(cursor);if(parent===cursor)break;cursor=parent;}}throw new Error('DROP8 프로젝트 루트를 찾지 못했습니다. 실행기를 프로젝트 최상위 폴더에 넣으세요.');}
function atomicWrite(path:string,content:string){mkdirSync(dirname(path),{recursive:true});const tmp=`${path}.drop8-${process.pid}-${Date.now()}.tmp`;writeFileSync(tmp,content,'utf8');renameSync(tmp,path);}
function validatePackage(root:string){const pkg=JSON.parse(read(join(root,'package.json')));if(pkg.name!=='drop8-source')throw new Error(`예상 프로젝트가 아닙니다: ${pkg.name??'unknown'}`);}
function validateProtected(root:string){
 const room=read(join(root,'server/src/rooms/Drop8Room.ts'));
 for(const marker of ['DROP8_REFACTOR_023_AI_SAFE_ZONE_SWEEP_LIVE_SPECTATOR_DIALOGUE','DROP8_AI_PATROL_STABILITY_HOTFIX','DROP8_AI_LARGE_BUILDING_PERIMETER_HOTFIX'])if(!room.includes(marker))throw new Error(`보호 대상 기존 마커 누락: ${marker}`);
 if(!room.includes(payload.priorMarker))throw new Error(`직전 단계 마커가 없습니다: ${payload.priorMarker}. 먼저 Refactor 024E를 적용하세요.`);
}
function state(root:string){let applied=0,before=0;const conflicts:string[]=[];for(const entry of payload.entries){const target=join(root,safe(entry.path));if(!existsSync(target)){if(entry.mode==='create')before++;else conflicts.push(`${entry.path}(누락)`);continue;}const digest=sha(readFileSync(target));if(digest===entry.afterSha256)applied++;else if(entry.mode==='modify'&&entry.acceptedBeforeSha256.includes(digest))before++;else conflicts.push(`${entry.path}(Refactor 024E 기준과 다른 내용)`);}return{applied,before,conflicts,total:payload.entries.length};}
function backupAndWrite(root:string){
 const backup=join(root,'patch_backups',BACKUP_NAME,timestamp()),pre=join(backup,'preimage');mkdirSync(pre,{recursive:true});
 const manifest:Manifest={patchId:PATCH_ID,patchFile:PATCH_FILE,createdAt:new Date().toISOString(),projectRoot:root,files:[],createdFiles:[],generatedDirs:[]};
 for(const entry of payload.entries){const rel=safe(entry.path),target=join(root,rel),existed=existsSync(target);if(existed){const original=readFileSync(target),backupFile=join(pre,rel);mkdirSync(dirname(backupFile),{recursive:true});copyFileSync(target,backupFile);const text=original.toString('utf8');manifest.files.push({path:rel,existed:true,beforeSha256:sha(original),eol:eol(text),bom:hasBom(text)});}else{manifest.files.push({path:rel,existed:false,beforeSha256:'',eol:'LF',bom:false});manifest.createdFiles.push(rel);}}
 for(const rel of ['shared/dist','client/dist','server/build']){const target=join(root,rel),existed=existsSync(target);manifest.generatedDirs.push({path:rel,existed});if(existed){const dest=join(backup,'generated-preimage',rel);mkdirSync(dirname(dest),{recursive:true});cpSync(target,dest,{recursive:true,preserveTimestamps:true});}}
 writeFileSync(join(backup,'manifest.json'),JSON.stringify(manifest,null,2),'utf8');
 for(const entry of payload.entries)atomicWrite(join(root,safe(entry.path)),entry.content);
 return backup;
}
function latestBackup(root:string){const base=join(root,'patch_backups',BACKUP_NAME);if(!existsSync(base))throw new Error(`백업 폴더가 없습니다: ${base}`);const dirs=readdirSync(base).filter((name)=>existsSync(join(base,name,'manifest.json'))).sort().reverse();if(!dirs[0])throw new Error('복원 가능한 백업이 없습니다.');return join(base,dirs[0]);}
function rollback(root:string,arg?:string){const backup=arg?(isAbsolute(arg)?arg:resolve(root,arg)):latestBackup(root),manifestPath=join(backup,'manifest.json');if(!existsSync(manifestPath))throw new Error(`manifest 누락: ${manifestPath}`);const manifest=JSON.parse(read(manifestPath)) as Manifest;if(manifest.patchId!==PATCH_ID)throw new Error(`다른 패치 백업입니다: ${manifest.patchId}`);for(const item of [...manifest.files].reverse()){const target=join(root,safe(item.path));if(item.existed){const source=join(backup,'preimage',safe(item.path));if(!existsSync(source))throw new Error(`백업 파일 누락: ${item.path}`);mkdirSync(dirname(target),{recursive:true});copyFileSync(source,target);}else rmSync(target,{force:true});}for(const dir of manifest.generatedDirs){const target=join(root,safe(dir.path));rmSync(target,{recursive:true,force:true});if(dir.existed){const source=join(backup,'generated-preimage',safe(dir.path));if(existsSync(source))cpSync(source,target,{recursive:true,preserveTimestamps:true});}}console.log(`[${PATCH_ID}] 롤백 완료: ${backup}`);}
function verifyAfter(root:string){for(const entry of payload.entries){const target=join(root,safe(entry.path));if(!existsSync(target)||sha(readFileSync(target))!==entry.afterSha256)throw new Error(`적용 후 무결성 실패: ${entry.path}`);}}
function run(label:string,command:string,root:string,log:string){console.log(`
[${PATCH_ID}] ${label}
> ${command}`);const result=spawnSync(command,{cwd:root,shell:true,encoding:'utf8',maxBuffer:128*1024*1024,env:process.env});writeFileSync(log,`
### ${label}
> ${command}
exit=${result.status}
${result.stdout??''}
${result.stderr??''}
`,{encoding:'utf8',flag:'a'});if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);if(result.error)throw result.error;if(result.status!==0)throw new Error(`${label} 실패 (exit=${result.status})`);}

const root=findRoot();process.chdir(root);console.log(`[${PATCH_ID}] 프로젝트 루트: ${root}`);
if(rollbackIndex>=0){const arg=args[rollbackIndex+1]&&!args[rollbackIndex+1]!.startsWith('--')?args[rollbackIndex+1]:undefined;rollback(root,arg);process.exit(0);}
validatePackage(root);validateProtected(root);const current=state(root);if(current.conflicts.length)throw new Error(`기준 코드 충돌: ${current.conflicts.join(', ')}
Refactor 024E 적용 뒤 수동 수정이 있다면 최신 ZIP을 다시 전달해 실행기를 재생성하세요.`);if(current.applied===current.total){verifyAfter(root);console.log(`[${PATCH_ID}] 이미 정상 적용되어 있습니다.`);process.exit(0);}if(current.applied>0)throw new Error(`부분 적용 상태(${current.applied}/${current.total})입니다. 자동 진행하지 않습니다.`);
console.log(`[${PATCH_ID}] 직전 단계 확인: ${payload.priorMarker}`);
console.log(`[${PATCH_ID}] AI는 전투·리스폰에 참여하지만 목표 킬과 인간 순위에서 제외됩니다.`);
console.log(`[${PATCH_ID}] 기존 Battle Royale, Refactor 021~024E, 수동 AI 경로 핫픽스를 보존합니다.`);
console.log(`
[${PATCH_ID}] 변경 예정 파일:`);for(const entry of payload.entries)console.log(` - [${entry.mode==='create'?'신규':'수정'}] ${entry.path} :: ${entry.purpose}`);
console.log(`[${PATCH_ID}] 검증: typecheck → lint → 025 집중 테스트 → 024E/Room 회귀 → 전체 test → build → git diff --check`);
if(dryRun){console.log(`
[${PATCH_ID}] dry-run 성공: 실제 파일과 백업을 만들지 않았습니다.`);process.exit(0);}
const backup=backupAndWrite(root),log=join(backup,'verification-log.txt');writeFileSync(log,'','utf8');
try{verifyAfter(root);if(forceFail)throw new Error('DROP8_PATCH_FORCE_FAIL=1 강제 실패');if(!internal){
 run('TypeScript typecheck','pnpm run typecheck',root,log);
 run('ESLint','pnpm run lint',root,log);
 run('Refactor 025 집중 테스트','pnpm --filter @drop8/server exec vitest run tests/refactor025-open-arena-kill-limit.test.ts tests/refactor025-open-arena-round-source.test.ts tests/refactor025-open-arena-ux-source.test.ts --pool=threads --maxWorkers=1 --no-file-parallelism --testTimeout=30000 --hookTimeout=30000 --reporter=verbose',root,log);
 run('Refactor 024E 및 Room 회귀 테스트','pnpm --filter @drop8/server exec vitest run tests/refactor024e-arena-scoreboard.test.ts tests/refactor024e-arena-ux-source.test.ts tests/refactor024c-open-arena-respawn.test.ts tests/refactor024d-world-cleanup.test.ts tests/room.test.ts --pool=threads --maxWorkers=1 --no-file-parallelism --testTimeout=30000 --hookTimeout=30000 --reporter=verbose',root,log);
 run('전체 테스트','pnpm run test',root,log);
 run('전체 빌드','pnpm run build',root,log);
 const paths=payload.entries.map((entry)=>`"${entry.path}"`).join(' ');run('대상 git diff check',`git diff --check -- ${paths}`,root,log);
}else console.log(`[${PATCH_ID}] 내부 복제본 검증 모드: pnpm 명령 생략`);
console.log(`
[${PATCH_ID}] 적용 성공`);console.log(`[${PATCH_ID}] 백업: ${backup}`);console.log(`[${PATCH_ID}] 롤백 CMD: node --experimental-strip-types ${PATCH_FILE} --rollback`);
}catch(error){console.error(`
[${PATCH_ID}] 검증 실패. 전체 자동 롤백합니다.`);try{rollback(root,backup);}catch(rollbackError){console.error('자동 롤백 오류',rollbackError);}console.error(`[${PATCH_ID}] 백업: ${backup}`);throw error;}
